with feeders as (
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__SCRUTINY_NO))) as HUB_ASSESSMENT_HK
        , APPOINTMENT_CODE as ASSESSMENT_REFERENCE_NUMBER
        , PRIORITY_FLAG as PRIORITY
        , TYPE_OF_CHECKUP as ASSESSMENT_TYPE
        , CHECKUP_AMT as COST_OF_ASSESSMENT
        , STATUS_DESC as ASSESSMENT_STATUS
        , REMARKS as OUTCOME_SUMMARY
        , APP_DATE as SCHEDULED_DATE
        , cast(null as varchar) as CONDUCTED_DATE
        , cast(null as varchar) as ASSESSOR_REFERENCE
        , cast(null as varchar) as COMPLETED_DATE
        , cast(null as varchar) as TRIGGER_EVENT
        , 'BA_HCP_PP_MEM_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_pp_mem_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__PD_SCRUTINY_NUMBER))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as ASSESSMENT_REFERENCE_NUMBER
        , cast(null as varchar) as PRIORITY
        , cast(null as varchar) as ASSESSMENT_TYPE
        , cast(null as varchar) as COST_OF_ASSESSMENT
        , PLC_MEDICAL_TEST_ALRDY_CON as ASSESSMENT_STATUS
        , cast(null as varchar) as OUTCOME_SUMMARY
        , cast(null as varchar) as SCHEDULED_DATE
        , cast(null as varchar) as CONDUCTED_DATE
        , cast(null as varchar) as ASSESSOR_REFERENCE
        , cast(null as varchar) as COMPLETED_DATE
        , cast(null as varchar) as TRIGGER_EVENT
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_SCRUTINY_NUMBER),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__ASSESS_ID))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as ASSESSMENT_REFERENCE_NUMBER
        , cast(null as varchar) as PRIORITY
        , cast(null as varchar) as ASSESSMENT_TYPE
        , cast(null as varchar) as COST_OF_ASSESSMENT
        , cast(null as varchar) as ASSESSMENT_STATUS
        , cast(null as varchar) as OUTCOME_SUMMARY
        , cast(null as varchar) as SCHEDULED_DATE
        , ASSESSMENT_SDATE as CONDUCTED_DATE
        , cast(null as varchar) as ASSESSOR_REFERENCE
        , ASSESSMENT_EDATE as COMPLETED_DATE
        , cast(null as varchar) as TRIGGER_EVENT
        , 'BJAZ_HM_PRO_ASSESSMENT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_pro_assessment') }}
    where (nullif(trim(ASSESS_ID),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__SCRUTINY_NO))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as ASSESSMENT_REFERENCE_NUMBER
        , cast(null as varchar) as PRIORITY
        , cast(null as varchar) as ASSESSMENT_TYPE
        , cast(null as varchar) as COST_OF_ASSESSMENT
        , STATUS as ASSESSMENT_STATUS
        , cast(null as varchar) as OUTCOME_SUMMARY
        , cast(null as varchar) as SCHEDULED_DATE
        , cast(null as varchar) as CONDUCTED_DATE
        , cast(null as varchar) as ASSESSOR_REFERENCE
        , cast(null as varchar) as COMPLETED_DATE
        , cast(null as varchar) as TRIGGER_EVENT
        , 'BJAZ_SCR_HLTH_PORTABLE_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_scr_hlth_portable_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__SCRUTINY_NO))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as ASSESSMENT_REFERENCE_NUMBER
        , cast(null as varchar) as PRIORITY
        , cast(null as varchar) as ASSESSMENT_TYPE
        , cast(null as varchar) as COST_OF_ASSESSMENT
        , cast(null as varchar) as ASSESSMENT_STATUS
        , cast(null as varchar) as OUTCOME_SUMMARY
        , cast(null as varchar) as SCHEDULED_DATE
        , cast(null as varchar) as CONDUCTED_DATE
        , INSERTED_BY as ASSESSOR_REFERENCE
        , cast(null as varchar) as COMPLETED_DATE
        , cast(null as varchar) as TRIGGER_EVENT
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__CONTRACT_ID_CLAIM_ID_RISK_ID))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as ASSESSMENT_REFERENCE_NUMBER
        , cast(null as varchar) as PRIORITY
        , cast(null as varchar) as ASSESSMENT_TYPE
        , cast(null as varchar) as COST_OF_ASSESSMENT
        , cast(null as varchar) as ASSESSMENT_STATUS
        , cast(null as varchar) as OUTCOME_SUMMARY
        , cast(null as varchar) as SCHEDULED_DATE
        , cast(null as varchar) as CONDUCTED_DATE
        , cast(null as varchar) as ASSESSOR_REFERENCE
        , cast(null as varchar) as COMPLETED_DATE
        , TRIGGER_TYPE as TRIGGER_EVENT
        , 'BJAZ_RISK_TRANS_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_risk_trans_dtls') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|' || coalesce(nullif(trim(CLAIM_ID),''),'') || '|' || coalesce(nullif(trim(RISK_ID),''),''), '||'))))) is not null
),

resolved as (
    select
        HUB_ASSESSMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSMENT_REFERENCE_NUMBER end) as ASSESSMENT_REFERENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRIORITY end) as PRIORITY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSMENT_TYPE end) as ASSESSMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COST_OF_ASSESSMENT end) as COST_OF_ASSESSMENT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSMENT_STATUS end) as ASSESSMENT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OUTCOME_SUMMARY end) as OUTCOME_SUMMARY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SCHEDULED_DATE end) as SCHEDULED_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONDUCTED_DATE end) as CONDUCTED_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ASSESSOR_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSOR_REFERENCE end)) as ASSESSOR_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COMPLETED_DATE end) as COMPLETED_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then TRIGGER_EVENT end) as TRIGGER_EVENT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ASSESSMENT_HK
),

hashed as (
    select
        *,
        case when ASSESSMENT_REFERENCE_NUMBER is not null or PRIORITY is not null or ASSESSMENT_TYPE is not null or COST_OF_ASSESSMENT is not null or ASSESSMENT_STATUS is not null or OUTCOME_SUMMARY is not null or SCHEDULED_DATE is not null or CONDUCTED_DATE is not null or ASSESSOR_REFERENCE is not null or COMPLETED_DATE is not null or TRIGGER_EVENT is not null
                     then md5(upper(coalesce(cast(ASSESSMENT_REFERENCE_NUMBER as varchar), '') || '|' || coalesce(cast(PRIORITY as varchar), '') || '|' || coalesce(cast(ASSESSMENT_TYPE as varchar), '') || '|' || coalesce(cast(COST_OF_ASSESSMENT as varchar), '') || '|' || coalesce(cast(ASSESSMENT_STATUS as varchar), '') || '|' || coalesce(cast(OUTCOME_SUMMARY as varchar), '') || '|' || coalesce(cast(SCHEDULED_DATE as varchar), '') || '|' || coalesce(cast(CONDUCTED_DATE as varchar), '') || '|' || coalesce(cast(ASSESSOR_REFERENCE as varchar), '') || '|' || coalesce(cast(COMPLETED_DATE as varchar), '') || '|' || coalesce(cast(TRIGGER_EVENT as varchar), '')))
                end as SAT_ASSESSMENT_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_ASSESSMENT_HK is not null
  and SAT_ASSESSMENT_HEADER_HASHDIFF is not null
